@Component("anomaly-handler")
@ProcessingGroup("anomaly-processing-group")
public class AnomalyEventHandler {
	
	// core constructor
	AnomalyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAnomalyEvent
     */
    @EventHandler
    public void handle( CreateAnomalyEvent event) {
        entityManager.persist(new Anomaly(event.getAnomalyId(), event.getOccurredAt(), event.getDetails(), event.getTimeSeries(), event.getAlert(), event.getDataset(), event.getAnomalyType(), event.getSeverity()));
    }

    /*
     * @param	event UpdateAnomalyEvent
     */
    @EventHandler
    public Anomaly handle( UpdateAnomalyEvent event) {
    	entityManager.merge(new Anomaly(event.getAnomalyId(), event.getOccurredAt(), event.getDetails(), event.getTimeSeries(), event.getAlert(), event.getDataset(), event.getAnomalyType(), event.getSeverity()));
    }
    
    /*
     * @param	event DeleteAnomalyEvent
     */
    @EventHandler
    public void on( DeleteAnomalyEvent event) {
    	Anomaly entity = new Anomaly();
   
    	// ------------------------------------------
    	// apply the AnomalyId
    	// ------------------------------------------
    	entity.setAnomalyId( event.getAnomalyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AnomalyRepository anomalyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AnomalyEventHandler.class.getName());

}
